def sync():
    # 1. Save dictionary to data/verified_frame_transcripts.json
    with open(VERIFIED_PATH, "w", encoding="utf-8") as f:
        json.dump(VERIFIED_TRANSCRIPTS, f, ensure_ascii=False, indent=2)
    print(f"[+] Saved {len(VERIFIED_TRANSCRIPTS)} verified transcripts to {VERIFIED_PATH}")

    # 2. Update data/scripts-db.json
    with open(DB_PATH, "r", encoding="utf-8") as f:
        db = json.load(f)

    updated_count = 0
    for s in db.get("scripts", []):
        url = s.get("source_url", "")
        m = re.search(r"/(?:reel|p)/([A-Za-z0-9_-]+)", url)
        code = m.group(1) if m else None
        
        if code and code in VERIFIED_TRANSCRIPTS:
            v = VERIFIED_TRANSCRIPTS[code]
            s["title"] = v["title"]
            s["content"] = v["content"]
            s["extracted_raw_text"] = v["content"]
            s["caption"] = v["caption"]
            lines = [l.strip() for l in v["content"].split("\n") if l.strip()]
            s["hook"] = lines[0] if lines else s.get("hook", "")
            s["punchline"] = lines[-1] if lines else s.get("punchline", "")
            s["lines_count"] = len(lines)
            s["words_count"] = len(v["content"].split())
            s["frame_transcript_verified"] = True
            updated_count += 1
            print(f"  [DB Updated] {s.get('id')} ({code}) -> {s.get('scheduled_date')} slot {s.get('scheduled_slot')}")

    with open(DB_PATH, "w", encoding="utf-8") as f:
        json.dump(db, f, ensure_ascii=False, indent=2)
    print(f"[+] scripts-db.json updated: {updated_count} scripts synchronized!")

    # 3. Update data/hunted-21-verified-from-tuesday.json if exists
    if os.path.exists(H21_PATH):
        with open(H21_PATH, "r", encoding="utf-8") as f:
            h21 = json.load(f)
        items = h21 if isinstance(h21, list) else h21.get("scripts", h21.get("reels", []))
        h21_count = 0
        for s in items:
            url = s.get("source_url", "")
            m = re.search(r"/(?:reel|p)/([A-Za-z0-9_-]+)", url)
            code = m.group(1) if m else None
            if code and code in VERIFIED_TRANSCRIPTS:
                v = VERIFIED_TRANSCRIPTS[code]
                s["title"] = v["title"]
                s["content"] = v["content"]
                s["extracted_raw_text"] = v["content"]
                s["caption"] = v["caption"]
                s["frame_transcript_verified"] = True
                h21_count += 1
        with open(H21_PATH, "w", encoding="utf-8") as f:
            json.dump(h21, f, ensure_ascii=False, indent=2)
        print(f"[+] hunted-21-verified-from-tuesday.json updated: {h21_count} scripts synchronized!")

if __name__ == "__main__":
    sync()
